 104 // fetchRepoMeta calls the generic /v1/repositories/{name} endpoint.
 105 // Returns type, format and any memberNames found in attributes, or an error when
 106 // the manager could not be asked.
 107 // Some Nexus deployments include memberNames in attributes.group without requiring admin privilege.
 108 func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string, info RegistryInfo) (repoType, format string, members []GroupMember, err error) {
 109     endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
 110     body, err := n.nexusGET(ctx, endpoint, info)
 111     if err != nil {
 112         log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
 113         return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
 114     }
 115     if len(bytes.TrimSpace(body)) == 0 {
 116         log.Printf("INFO [registrymgr/nexus] meta %q: empty reply", repoName)
 117         return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errEmptyReply)
 118     }
 119     var result struct {
 120         Type   string `json:"type"`
 121         Format string `json:"format"`
 122         Group  struct {
 123             MemberNames []string `json:"memberNames"`
 124         } `json:"group"`
 125         Attributes struct {
 126             Group struct {
 127                 MemberNames []string `json:"memberNames"`
 128             } `json:"group"`
 129         } `json:"attributes"`
 130     }
 131     if err := json.Unmarshal(body, &result); err != nil {
 132         log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
 133         return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, err)
 134     }
 135     if result.Type == "" {
 136         // Valid JSON that is not a repository document: `{}`, `null`.
 137         log.Printf("INFO [registrymgr/nexus] meta %q: reply names no repository type", repoName)
 138         return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errNoRepositoryType)
 139     }
 140     log.Printf("INFO [registrymgr/nexus] meta %q: type=%s format=%s", repoName, result.Type, result.Format)
 141 
 142     // Collect memberNames from whichever field Nexus populated.
 143     rawNames := result.Group.MemberNames
 144     if len(rawNames) == 0 {
 145         rawNames = result.Attributes.Group.MemberNames
 146     }
 147     members = memberList(info.URL, rawNames)
 148     return result.Type, result.Format, members, nil
 149 }
 150 
 151 // fetchGroupMembers calls the format-specific group endpoint which reliably
 152 // includes memberNames: GET /v1/repositories/{format}/group/{name}
 153 // Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
 154 func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) []GroupMember {
 155     if format == "" {
 156         format = "docker"
 157     }
 158     endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, format, repoName)
 159     body, err := n.nexusGET(ctx, endpoint, info)
 160     if err != nil {
 161         // When auth is present but the request fails, retry anonymously.
 162         // Some Nexus instances allow anonymous read of the group admin endpoint.
 163         // A refused redirect to another origin is not such a failure: the
 164         // detection stops there (DEVDESK-412), no silent anonymous retry.
 165         if info.Username != "" && info.Password != "" && !errors.Is(err, oci.ErrOffOriginRedirect) {
 166             anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
 167             body, err = n.nexusGET(ctx, endpoint, anonInfo)
 168         }
 169     }
 170     if errors.Is(err, oci.ErrOffOriginRedirect) {
 171         // The advice below is for an account Nexus refused, not for this.
 172         log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — redirect to another origin refused (the registry URL may need to be the one Nexus serves)", endpoint, err)
 173         return nil
 174     }
 175     if err != nil {
 176         log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
 177         return nil
 178     }
 179     var result struct {
 180         Group struct {
 181             MemberNames []string `json:"memberNames"`
 182         } `json:"group"`
 183     }
 184     if err := json.Unmarshal(body, &result); err != nil {
 185         return nil
 186     }
 187     return memberList(info.URL, result.Group.MemberNames)
 188 }
