 190 // memberList turns the names a group declares into addresses.
 191 func memberList(dockerURL string, names []string) []GroupMember {
 192     members := make([]GroupMember, 0, len(names))
 193     for _, name := range names {
 194         url, prefix := memberAddress(dockerURL, name)
 195         members = append(members, GroupMember{
 196             Alias:      cleanMemberAlias(name),
 197             URL:        url,
 198             RepoPrefix: prefix,
 199         })
 200     }
 201     return members
 202 }
